import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileHandling {
    public void readUserFile(String userInput) throws IOException {
        // Secure approach: Validate and sanitize user input
        // Normalize the path to prevent directory traversal
        Path basePath = Paths.get("/user/documents/").toAbsolutePath().normalize();
        Path resolvedPath = basePath.resolve(userInput).normalize();

        // Ensure the resolved path is within the intended directory
        if (!resolvedPath.startsWith(basePath)) {
            throw new SecurityException("Invalid file path");
        }

        // Safely create or access the file
        File file = resolvedPath.toFile();
        file.createNewFile();
    }
}
```

